import boto3

def embed_output(output_text):
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        model_id='amazon.titan-embed-text-v1',
        body={
            'inputText': output_text
        }
    )
    result = json.loads(response['body'].read())
    return result['embedding']

if __name__ == '__main__':
    output_text = 'Sample platform output text'
    embedding = embed_output(output_text)
    print(embedding)

import boto3

def check_unsafe_content(text):
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        model_id='amazon.titan-text-express-v1',
        body={
            'inputText': text,
            'textGenerationConfig': {
                'maxTokenCount': 4096,
                'stopSequences': [],
                'temperature': 0,
                'topP': 0.9
            }
        }
    )
    result = json.loads(response['body'].read())
    output_text = result['results'][0]['outputText']
    safety_check = result['results'][0]['safetyCheck']
    if safety_check['status'] == 'unsafe':
        print('Unsafe content detected:', output_text)
    else:
        print('Content is safe:', output_text)

if __name__ == '__main__':
    sample_text = 'This is a sample text to check for unsafe content.'
    check_unsafe_content(sample_text)

from botocore.exceptions import ClientError


def create_model(model_name, model_version, model_description):
    try:
        bedrock_client = boto3.client('bedrock')
        response = bedrock_client.create_model(
            ModelName=model_name,
            ModelVersion=model_version,
            ModelDescription=model_description
        )
        return response
    except ClientError as e:
        print(f"Error creating model: {e}")
        return None


def get_model(model_name):
    try:
        bedrock_client = boto3.client('bedrock')
        response = bedrock_client.get_model(ModelName=model_name)
        return response
    except ClientError as e:
        print(f"Error getting model: {e}")
        return None


def normalize_model_response(response):
    if response is None:
        return None
    normalized_response = {
        'ModelName': response.get('ModelName', ''),
        'ModelVersion': response.get('ModelVersion', ''),
        'ModelDescription': response.get('ModelDescription', '')
    }
    return normalized_response

import boto3

def collect_platform_metadata():
    bedrock_client = boto3.client('bedrock', region_name='us-west-2')
    model_id = 'amazon.titan-text-express-v1'
    response = bedrock_client.invoke_model(
        modelId=model_id,
        body={
            'inputText': 'Hello, world!'
        }
    )
    model_output = response['body'].read().decode('utf-8')
    usage = response['usage']
    resource_id = response['responseMetadata']['RequestId']
    model_handle = response['modelId']
    return {
        'model_output': model_output,
        'usage': usage,
        'resource_id': resource_id,
        'model_handle': model_handle
    }

if __name__ == '__main__':
    metadata = collect_platform_metadata()
    print(metadata)

import boto3

bedrock = boto3.client('bedrock-runtime')

model_id = 'amazon.titan-text-express-v1'

def generate_stream(prompt):
    body = {
        'inputText': prompt,
        'textGenerationConfig': {
            'maxTokenCount': 4096,
            'temperature': 0,
            'topP': 0.9
        }
    }

    response = bedrock.invoke_model(
        body=json.dumps(body),
        modelId=model_id,
        accept='application/json',
        contentType='application/json'
    )

    response_body = json.loads(response.get('body').read())

    for event in response_body.get('results'):
        yield event

import boto3

def invoke_platform_model():
    client = boto3.client('bedrock-runtime', region_name='us-west-2')
    model_id = 'amazon.bedrock.model.v1'
    payload = {
        'inputText': 'Hello, world!'
    }
    response = client.invoke_model(
        modelId=model_id,
        body=payload
    )
    return response

